import{_ as e,c as p,b as s,a as t,d as l,e as o,r as c,o as i}from"./app-Ds2R91U1.js";const u="/assets/image-20260122175954139-DbPtITcq.png",r="/assets/image-20260122215202066-BqsLKns6.png",k={},d={href:"https://redis.io/docs/latest/operate/rs/databases/memory-performance/eviction-policy/",target:"_blank",rel:"noopener noreferrer"};function m(v,n){const a=c("ExternalLinkIcon");return i(),p("div",null,[n[1]||(n[1]=s("blockquote",null,[s("p",null,"本文介绍了redis的过期策略（惰性过期、定时过期）以及八种淘汰策略，然后分析了redis的LRU算法以及如何解决LFU算法的时效性问题")],-1)),s("p",null,[s("a",d,[n[0]||(n[0]=l("参考资料",-1)),o(a)])]),n[2]||(n[2]=t(`<p>redis是内存数据库，所有的操作都是基于内存的，所以它执行起来非常快。我们可以通过配置<code>maxmemory</code>参数来设置redis能够使用的内存大小。在64位操作系统下默认的最大值是机器的最大内存，在32位的操作系统下，默认最大值是3gb，可以根据情况合理调整。</p><p>redis本身对内存也设计了一套管理策略，主要表现在<code>过期策略</code>和<code>淘汰策略</code></p><h2 id="_1、过期策略" tabindex="-1"><a class="header-anchor" href="#_1、过期策略"><span>1、过期策略</span></a></h2><p>redis的过期策略是指为了保证内存的利用率，对设置了过期时间的key中已经过期的key的回收策略，类似与垃圾回收释放空间再利用</p><h3 id="_1-1、惰性过期" tabindex="-1"><a class="header-anchor" href="#_1-1、惰性过期"><span>1.1、惰性过期</span></a></h3><p>redis在我们每次使用某个key的时候，都会去判断一下这个key有没有过期。也就是调用下面这个<code>expireIfNeeded</code>方法：</p><div class="language-c line-numbers-mode" data-highlighter="prismjs" data-ext="c" data-title="c"><pre><code><span class="line"><span class="token keyword">int</span> <span class="token function">expireIfNeeded</span><span class="token punctuation">(</span>redisDb <span class="token operator">*</span>db<span class="token punctuation">,</span> robj <span class="token operator">*</span>key<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token function">keyIsExpired</span><span class="token punctuation">(</span>db<span class="token punctuation">,</span>key<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">/* If we are running in the context of a slave, instead of </span>
<span class="line">     * evicting the expired key from the database, we return ASAP:</span>
<span class="line">     * the slave key expiration is controlled by the master that will</span>
<span class="line">     * send us synthesized DEL operations for expired keys.</span>
<span class="line">     *</span>
<span class="line">     * Still we try to return the right information to the caller,</span>
<span class="line">     * that is, 0 if we think the key should be still valid, 1 if</span>
<span class="line">     * we think the key is expired at this time. </span>
<span class="line">     */</span></span>
<span class="line">    <span class="token comment">//如果配置有masterhost，说明是从节点，那么不操作删除</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>server<span class="token punctuation">.</span>masterhost <span class="token operator">!=</span> <span class="token constant">NULL</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">/* Delete the key */</span></span>
<span class="line">    server<span class="token punctuation">.</span>stat_expiredkeys<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">propagateExpire</span><span class="token punctuation">(</span>db<span class="token punctuation">,</span>key<span class="token punctuation">,</span>server<span class="token punctuation">.</span>lazyfree_lazy_expire<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">notifyKeyspaceEvent</span><span class="token punctuation">(</span>NOTIFY_EXPIRED<span class="token punctuation">,</span> <span class="token string">&quot;expired&quot;</span><span class="token punctuation">,</span>key<span class="token punctuation">,</span>db<span class="token operator">-&gt;</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">//是否是异步删除，防止单个Key的数据量很大阻塞主线程，是4.0之后添加的新功能，默认关闭lazyfree-lazy-expire</span></span>
<span class="line">    <span class="token keyword">int</span> retval <span class="token operator">=</span> server<span class="token punctuation">.</span>lazyfree_lazy_expire <span class="token operator">?</span><span class="token function">dbAsyncDelete</span><span class="token punctuation">(</span>db<span class="token punctuation">,</span>key<span class="token punctuation">)</span> <span class="token operator">:</span> <span class="token function">dbSyncDelete</span><span class="token punctuation">(</span>db<span class="token punctuation">,</span>key<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>retval<span class="token punctuation">)</span> <span class="token function">signalModifiedKey</span><span class="token punctuation">(</span><span class="token constant">NULL</span><span class="token punctuation">,</span>db<span class="token punctuation">,</span>key<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> retval<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>因为这种方式是被动的，只有在对对应的key进行操作的时候才会去判断，所以叫“惰性过期”。因为不用一直盯着处理这些过期的key，虽然该策略最大化地节省了cpu的资源，但很明显惰性过期是有一定的问题的，比如空间释放不及时，如果这些key长时间没有使用，那它们很可能就会成为“僵尸”不会被清除，长时间占用内存空间</p><p>所以这就需要另外一个策略：定期主动过期</p><h3 id="_1-2、定期过期" tabindex="-1"><a class="header-anchor" href="#_1-2、定期过期"><span>1.2、定期过期</span></a></h3><p>定期过期策略是为了弥补惰性过期策略的不足。我们在之前分析redis的数据结构中提到过redis的rehash过程，当时有一个方法<code>serverCron</code>，其实从名字看就是一个定时任务，具体执行频率可以在<code>redis.conf</code>中通过设置<code>server.hz</code>来配置。此外，<code>serverCron</code>除了做rehash之外，还做了其它事情，比如：</p><ul><li>清理数据库中过期的键值对</li><li>更新数据库的各类统计信息，比如时间、内存占用、数据库占用情况等</li><li>关闭和清理连接失效的客户端</li><li>尝试进行持久化操作</li></ul><p>那么redis是怎么来扫描这些过期的key的呢？redis为了追求极致的性能，所以不可能将所有的key遍历一遍，就跟它的扩容一样，还是采用了渐进式思想，具体流程如下：</p><ul><li>1、<code>serverCron</code>定时去执行清理方法，具体的定时频率可配置，默认100ms</li><li>2、执行清理的时候不是扫描所有的key，而是扫描了设置了过期时间的key。也不是每次把所有过期的key都拿过来进行清理，因为如果过期的key比较多的时候，这个过程就会很慢</li><li>3、redis根据hash桶的维度来扫描，一次扫20个（默认值，可配）为止，如果第一个hash桶只扫到15个，则继续扫第二个hash桶。但是如果第二个桶不止5个，redis仍然会将第二个桶扫描完（秉承着来都来了的原则）</li><li>4、找到扫描到的key里边过期的key，进行删除</li><li>5、如果连续取了400个空桶，或者扫描到的过期key跟扫描的总数比例达到10%（可配），则继续循环执行3、4步</li><li>6、循环次数达到16次后，会进行时间检测，如果这个时间超过了指定的时间，则跳出。本次定时任务执行结束</li></ul><p>核心方法在<code>expire.c</code>的<code>activeExpireCycle</code>方法：</p><div class="language-c line-numbers-mode" data-highlighter="prismjs" data-ext="c" data-title="c"><pre><code><span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">define</span> <span class="token macro-name">ACTIVE_EXPIRE_CYCLE_KEYS_PER_LOOP</span> <span class="token expression"><span class="token number">20</span> </span><span class="token comment">/* Keys for each DB loop. */</span></span></span>
<span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">define</span> <span class="token macro-name">ACTIVE_EXPIRE_CYCLE_FAST_DURATION</span> <span class="token expression"><span class="token number">1000</span> </span><span class="token comment">/* Microseconds. */</span></span></span>
<span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">define</span> <span class="token macro-name">ACTIVE_EXPIRE_CYCLE_SLOW_TIME_PERC</span> <span class="token expression"><span class="token number">25</span> </span><span class="token comment">/* Max % of CPU to use. */</span></span></span>
<span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">define</span> <span class="token macro-name">ACTIVE_EXPIRE_CYCLE_ACCEPTABLE_STALE</span> <span class="token expression"><span class="token number">10</span> </span><span class="token comment">/* % of stale keys after which we do extra efforts. */</span></span></span>
<span class="line"><span class="token keyword">void</span> <span class="token function">activeExpireCycle</span><span class="token punctuation">(</span><span class="token keyword">int</span> type<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* Adjust the running parameters according to the configured expire </span>
<span class="line">     * effort. The default effort is 1, and the maximum configurable effort </span>
<span class="line">     * is 10. </span>
<span class="line">     */</span></span>
<span class="line">    <span class="token keyword">unsigned</span> <span class="token keyword">long</span> effort <span class="token operator">=</span> server<span class="token punctuation">.</span>active_expire_effort<span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token comment">/* Rescale from 0 to 9. */</span></span>
<span class="line">        config_keys_per_loop <span class="token operator">=</span> ACTIVE_EXPIRE_CYCLE_KEYS_PER_LOOP <span class="token operator">+</span> ACTIVE_EXPIRE_CYCLE_KEYS_PER_LOOP<span class="token operator">/</span><span class="token number">4</span><span class="token operator">*</span>effort<span class="token punctuation">,</span></span>
<span class="line">    config_cycle_fast_duration <span class="token operator">=</span> ACTIVE_EXPIRE_CYCLE_FAST_DURATION <span class="token operator">+</span> ACTIVE_EXPIRE_CYCLE_FAST_DURATION<span class="token operator">/</span><span class="token number">4</span><span class="token operator">*</span>effort<span class="token punctuation">,</span></span>
<span class="line">    config_cycle_slow_time_perc <span class="token operator">=</span> ACTIVE_EXPIRE_CYCLE_SLOW_TIME_PERC <span class="token operator">+</span> <span class="token number">2</span><span class="token operator">*</span>effort<span class="token punctuation">,</span></span>
<span class="line">    config_cycle_acceptable_stale <span class="token operator">=</span> ACTIVE_EXPIRE_CYCLE_ACCEPTABLE_STALEeffort<span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">/* This function has some global state in order to continue the work </span>
<span class="line">     * incrementally across calls. */</span></span>
<span class="line">    <span class="token keyword">static</span> <span class="token keyword">unsigned</span> <span class="token keyword">int</span> current_db <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> <span class="token comment">/* Last DB tested. */</span></span>
<span class="line">    <span class="token keyword">static</span> <span class="token keyword">int</span> timelimit_exit <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> <span class="token comment">/* Time limit hit in previous call? */</span></span>
<span class="line">    <span class="token keyword">static</span> <span class="token keyword">long</span> <span class="token keyword">long</span> last_fast_cycle <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> <span class="token comment">/* When last fast cycle ran. */</span></span>
<span class="line">    <span class="token keyword">int</span> j<span class="token punctuation">,</span> iteration <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">int</span> dbs_per_call <span class="token operator">=</span> CRON_DBS_PER_CALL<span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">long</span> <span class="token keyword">long</span> start <span class="token operator">=</span> <span class="token function">ustime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> timelimit<span class="token punctuation">,</span> elapsed<span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">/* When clients are paused the dataset should be static not just from the </span>
<span class="line">     * POV of clients not being able to write, but also from the POV of </span>
<span class="line">     * expires and evictions of keys not being performed. </span>
<span class="line">     */</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">clientsArePaused</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>type <span class="token operator">==</span> ACTIVE_EXPIRE_CYCLE_FAST<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">/* Don&#39;t start a fast cycle if the previous cycle did not exit </span>
<span class="line">         * for time limit, unless the percentage of estimated stale keys is </span>
<span class="line">         * too high. Also never repeat a fast cycle for the same period </span>
<span class="line">         * as the fast cycle total duration itself. */</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>timelimit_exit <span class="token operator">&amp;&amp;</span> server<span class="token punctuation">.</span>stat_expired_stale_perc <span class="token operator">&lt;</span> config_cycle_acceptable_stale<span class="token punctuation">)</span></span>
<span class="line">            <span class="token keyword">return</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>start <span class="token operator">&lt;</span> last_fast_cycle <span class="token operator">+</span> <span class="token punctuation">(</span>longlong<span class="token punctuation">)</span>config_cycle_fast_duration<span class="token operator">*</span><span class="token number">2</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token keyword">return</span><span class="token punctuation">;</span></span>
<span class="line">        last_fast_cycle <span class="token operator">=</span> start<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token comment">/* We usually should test CRON_DBS_PER_CALL per iteration, with </span>
<span class="line">     * two exceptions:</span>
<span class="line">     *</span>
<span class="line">     * 1) Don&#39;t test more DBs than we have. </span>
<span class="line">     * 2) If last time we hit the time limit, we want to scan all DBs </span>
<span class="line">     * in this iteration, as there is work to do in some DB and we don&#39;t want </span>
<span class="line">     * expired keys to use memory for too much time. */</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>dbs_per_call <span class="token operator">&gt;</span> server<span class="token punctuation">.</span>dbnum <span class="token operator">||</span> timelimit_exit<span class="token punctuation">)</span></span>
<span class="line">        dbs_per_call <span class="token operator">=</span> server<span class="token punctuation">.</span>dbnum<span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">/* We can use at max &#39;config_cycle_slow_time_perc&#39; percentage of CPU </span>
<span class="line">     * time per iteration. Since this function gets called with a frequency of </span>
<span class="line">     * server.hz times per second, the following is the max amount of </span>
<span class="line">     * microseconds we can spend in this function. */</span></span>
<span class="line">    timelimit <span class="token operator">=</span> config_cycle_slow_time_perc<span class="token operator">*</span><span class="token number">1000000</span><span class="token operator">/</span>server<span class="token punctuation">.</span>hz<span class="token operator">/</span><span class="token number">100</span><span class="token punctuation">;</span></span>
<span class="line">    timelimit_exit <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>timelimit <span class="token operator">&lt;=</span> <span class="token number">0</span><span class="token punctuation">)</span> timelimit <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>type <span class="token operator">==</span> ACTIVE_EXPIRE_CYCLE_FAST<span class="token punctuation">)</span></span>
<span class="line">        timelimit <span class="token operator">=</span> config_cycle_fast_duration<span class="token punctuation">;</span> <span class="token comment">/* in microseconds. */</span></span>
<span class="line">    <span class="token comment">/* Accumulate some global stats as we expire keys, to have some idea </span>
<span class="line">     * about the number of keys that are already logically expired, but still </span>
<span class="line">     * existing inside the database. */</span></span>
<span class="line">    <span class="token keyword">long</span> total_sampled <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">long</span> total_expired <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">//循环DB，可配，默认16</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span>j <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> j <span class="token operator">&lt;</span> dbs_per_call <span class="token operator">&amp;&amp;</span> timelimit_exit <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">;</span> j<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">/* Expired and checked in a single loop. */</span></span>
<span class="line">        <span class="token keyword">unsigned</span> <span class="token keyword">long</span> expired<span class="token punctuation">,</span> sampled<span class="token punctuation">;</span></span>
<span class="line">        redisDb <span class="token operator">*</span>db <span class="token operator">=</span> server<span class="token punctuation">.</span>db<span class="token operator">+</span><span class="token punctuation">(</span>current_db <span class="token operator">%</span>  server<span class="token punctuation">.</span>dbnum<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token comment">/* Increment the DB now so we are sure if we run out of time </span>
<span class="line">         * in the current DB we&#39;ll restart from the next. This allows to </span>
<span class="line">         * distribute the time evenly across DBs. */</span></span>
<span class="line">        current_db<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token comment">/* Continue to expire if at the end of the cycle there are still </span>
<span class="line">         * a big percentage of keys to expire, compared to the number of keys </span>
<span class="line">         * we scanned. The percentage, stored in config_cycle_acceptable_stale </span>
<span class="line">         * is not fixed, but depends on the Redis configured &quot;expire effort&quot;. */</span></span>
<span class="line">        <span class="token keyword">do</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">unsigned</span> <span class="token keyword">long</span> num<span class="token punctuation">,</span> slots<span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">long</span> <span class="token keyword">long</span> now<span class="token punctuation">,</span> ttl_sum<span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">int</span> ttl_samples<span class="token punctuation">;</span></span>
<span class="line">            iteration<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token comment">/* If there is nothing to expire try next DB ASAP. */</span></span>
<span class="line">            <span class="token comment">//如果没有过期key,循环下一个DB</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token punctuation">(</span>num <span class="token operator">=</span> <span class="token function">dictSize</span><span class="token punctuation">(</span>db<span class="token operator">-&gt;</span>expires<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                db<span class="token operator">-&gt;</span>avg_ttl <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">            slots <span class="token operator">=</span> <span class="token function">dictSlots</span><span class="token punctuation">(</span>db<span class="token operator">-&gt;</span>expires<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            now <span class="token operator">=</span> <span class="token function">mstime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token comment">/* When there are less than 1% filled slots, sampling the key </span>
<span class="line">             * space is expensive, so stop here waiting for better times... </span>
<span class="line">             * The dictionary will be resized asap. */</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>num <span class="token operator">&amp;&amp;</span> slots <span class="token operator">&gt;</span> DICT_HT_INITIAL_SIZE <span class="token operator">&amp;&amp;</span> <span class="token punctuation">(</span>num<span class="token operator">*</span><span class="token number">100</span><span class="token operator">/</span>slots <span class="token operator">&lt;</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token comment">/* The main collection cycle. Sample random keys among keys </span>
<span class="line">             * with an expire set, checking for expired ones. */</span></span>
<span class="line">            expired <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">            sampled <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">            ttl_sum <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">            ttl_samples <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token comment">//最多拿20个</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>num <span class="token operator">&gt;</span> config_keys_per_loop<span class="token punctuation">)</span></span>
<span class="line">                num <span class="token operator">=</span> config_keys_per_loop<span class="token punctuation">;</span></span>
<span class="line">            <span class="token comment">/* Here we access the low level representation of the hash table </span>
<span class="line">             * for speed concerns: this makes this code coupled with dict.c, </span>
<span class="line">             * but it hardly changed in ten years.</span>
<span class="line">             *</span>
<span class="line">             * Note that certain places of the hash table may be empty, </span>
<span class="line">             * so we want also a stop condition about the number of </span>
<span class="line">             * buckets that we scanned. However scanning for free buckets </span>
<span class="line">             * is very fast: we are in the cache line scanning a sequential </span>
<span class="line">             * array of NULL pointers, so we can scan a lot more buckets </span>
<span class="line">             * than keys in the same time. */</span></span>
<span class="line">            <span class="token keyword">long</span> max_buckets <span class="token operator">=</span> num<span class="token operator">*</span><span class="token number">20</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">long</span> checked_buckets <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token comment">//如果拿到的key大于20 或者 循环的checked_buckets大于400，跳出</span></span>
<span class="line">            <span class="token keyword">while</span> <span class="token punctuation">(</span>sampled <span class="token operator">&lt;</span> num <span class="token operator">&amp;&amp;</span> checked_buckets <span class="token operator">&lt;</span> max_buckets<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token comment">//遍历ht[0]、ht[1]</span></span>
<span class="line">                <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">int</span> table <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> table <span class="token operator">&lt;</span> <span class="token number">2</span><span class="token punctuation">;</span> table<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                    <span class="token keyword">if</span> <span class="token punctuation">(</span>table <span class="token operator">==</span> <span class="token number">1</span> <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span><span class="token function">dictIsRehashing</span><span class="token punctuation">(</span>db<span class="token operator">-&gt;</span>expires<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line">                    <span class="token keyword">unsigned</span> <span class="token keyword">long</span> idx <span class="token operator">=</span> db<span class="token operator">-&gt;</span>expires_cursor<span class="token punctuation">;</span><span class="token comment">//扫描到的位置</span></span>
<span class="line">                    idx <span class="token operator">&amp;=</span> db<span class="token operator">-&gt;</span>expires<span class="token operator">-&gt;</span>ht<span class="token punctuation">[</span>table<span class="token punctuation">]</span><span class="token punctuation">.</span>sizemask<span class="token punctuation">;</span></span>
<span class="line">                    <span class="token comment">//根据index拿到hash桶</span></span>
<span class="line">                    dictEntry <span class="token operator">*</span>de <span class="token operator">=</span> db<span class="token operator">-&gt;</span>expires<span class="token operator">-&gt;</span>ht<span class="token punctuation">[</span>table<span class="token punctuation">]</span><span class="token punctuation">.</span>table<span class="token punctuation">[</span>idx<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">                    <span class="token keyword">long</span> <span class="token keyword">long</span> ttl<span class="token punctuation">;</span></span>
<span class="line">                    <span class="token comment">/* Scan the current bucket of the current table. */</span></span>
<span class="line">                    checked_buckets<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">                    <span class="token comment">//循环hash桶里的所有key</span></span>
<span class="line">                    <span class="token keyword">while</span><span class="token punctuation">(</span>de<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                        <span class="token comment">/* Get the next entry now since this entry may get </span>
<span class="line">                             * deleted. */</span></span>
<span class="line">                        dictEntry <span class="token operator">*</span>e <span class="token operator">=</span> de<span class="token punctuation">;</span></span>
<span class="line">                        de <span class="token operator">=</span> de<span class="token operator">-&gt;</span>next<span class="token punctuation">;</span></span>
<span class="line">                        ttl <span class="token operator">=</span> <span class="token function">dictGetSignedIntegerVal</span><span class="token punctuation">(</span>e<span class="token punctuation">)</span><span class="token operator">-</span>now<span class="token punctuation">;</span></span>
<span class="line">                        <span class="token keyword">if</span><span class="token punctuation">(</span><span class="token function">activeExpireCycleTryExpire</span><span class="token punctuation">(</span>db<span class="token punctuation">,</span>e<span class="token punctuation">,</span>now<span class="token punctuation">)</span><span class="token punctuation">)</span> expired<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">                        <span class="token keyword">if</span> <span class="token punctuation">(</span>ttl <span class="token operator">&gt;</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                            <span class="token comment">/* We want the average TTL of keys yet</span>
<span class="line">                                 * not expired. </span>
<span class="line">                                 */</span></span>
<span class="line">                            ttl_sum <span class="token operator">+=</span> ttl<span class="token punctuation">;</span></span>
<span class="line">                            ttl_samples<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">                        <span class="token punctuation">}</span></span>
<span class="line">                        sampled<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">                    <span class="token punctuation">}</span></span>
<span class="line">                <span class="token punctuation">}</span></span>
<span class="line">                db<span class="token operator">-&gt;</span>expires_cursor<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">            total_expired <span class="token operator">+=</span> expired<span class="token punctuation">;</span> <span class="token comment">//过期的key数量</span></span>
<span class="line">            total_sampled <span class="token operator">+=</span> sampled<span class="token punctuation">;</span> <span class="token comment">//扫描的key数量</span></span>
<span class="line">            <span class="token comment">/* Update the average TTL stats for this database. */</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>ttl_samples<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token keyword">long</span> <span class="token keyword">long</span> avg_ttl <span class="token operator">=</span> ttl_sum<span class="token operator">/</span>ttl_samples<span class="token punctuation">;</span></span>
<span class="line">                <span class="token comment">/* Do a simple running average with a few samples. </span>
<span class="line">                 * We just use the current estimate with a weight of 2% </span>
<span class="line">                 * and the previous estimate with a weight of 98%. */</span></span>
<span class="line">                <span class="token keyword">if</span> <span class="token punctuation">(</span>db<span class="token operator">-&gt;</span>avg_ttl <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">)</span> db<span class="token operator">-&gt;</span>avg_ttl <span class="token operator">=</span> avg_ttl<span class="token punctuation">;</span></span>
<span class="line">                db<span class="token operator">-&gt;</span>avg_ttl <span class="token operator">=</span> <span class="token punctuation">(</span>db<span class="token operator">-&gt;</span>avg_ttl<span class="token operator">/</span><span class="token number">50</span><span class="token punctuation">)</span><span class="token operator">*</span><span class="token number">49</span> <span class="token operator">+</span> <span class="token punctuation">(</span>avg_ttl<span class="token operator">/</span><span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">            <span class="token comment">/* We can&#39;t block forever here even if there are many keys to </span>
<span class="line">             * expire. So after a given amount of milliseconds return to the </span>
<span class="line">             * caller waiting for the other active expire cycle. */</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token punctuation">(</span>iteration <span class="token operator">&amp;</span> <span class="token number">0xf</span><span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token comment">/* check once every 16 iterations. */</span></span>
<span class="line">                <span class="token comment">//16次循环判断一次时间，看有没有超过设置的时间阈值</span></span>
<span class="line">                elapsed <span class="token operator">=</span> <span class="token function">ustime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-</span>start<span class="token punctuation">;</span></span>
<span class="line">                <span class="token keyword">if</span> <span class="token punctuation">(</span>elapsed <span class="token operator">&gt;</span> timelimit<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                    timelimit_exit <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line">                    server<span class="token punctuation">.</span>stat_expired_time_cap_reached_count<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">                    <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token punctuation">}</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">            <span class="token comment">/* We don&#39;t repeat the cycle for the current database if there are </span>
<span class="line">             * an acceptable amount of stale keys (logically expired but yet </span>
<span class="line">             * not reclaimed). */</span></span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">while</span> <span class="token punctuation">(</span>sampled <span class="token operator">==</span> <span class="token number">0</span> <span class="token operator">||</span> <span class="token punctuation">(</span>expired<span class="token operator">*</span><span class="token number">100</span><span class="token operator">/</span>sampled<span class="token punctuation">)</span> <span class="token operator">&gt;</span> config_cycle_acceptable_stale<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 过期的数量 * 100/扫描的数量 = 配置的过期比例，默认10%</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    elapsed <span class="token operator">=</span> <span class="token function">ustime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-</span>start<span class="token punctuation">;</span>     <span class="token comment">//前面的循环里的时间检测用到</span></span>
<span class="line">    server<span class="token punctuation">.</span>stat_expire_cycle_time_used <span class="token operator">+=</span> elapsed<span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">latencyAddSampleIfNeeded</span><span class="token punctuation">(</span><span class="token string">&quot;expire-cycle&quot;</span><span class="token punctuation">,</span>elapsed<span class="token operator">/</span><span class="token number">1000</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">/* Update our estimate of keys existing but yet to be expired. </span>
<span class="line">     * Running average with this sample accounting for 5%. </span>
<span class="line">     */</span></span>
<span class="line">    <span class="token keyword">double</span> current_perc<span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>total_sampled<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        current_perc <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">double</span><span class="token punctuation">)</span>total_expired<span class="token operator">/</span>total_sampled<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">else</span></span>
<span class="line">        current_perc <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    server<span class="token punctuation">.</span>stat_expired_stale_perc <span class="token operator">=</span> <span class="token punctuation">(</span>current_perc<span class="token operator">*</span><span class="token number">0.05</span><span class="token punctuation">)</span><span class="token operator">+</span><span class="token punctuation">(</span>server<span class="token punctuation">.</span>stat_expired_stale_perc<span class="token operator">*</span><span class="token number">0.95</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_2、淘汰策略" tabindex="-1"><a class="header-anchor" href="#_2、淘汰策略"><span>2、淘汰策略</span></a></h2><p>redis的淘汰策略是指在内存不够用的情况下，内存释放的一种策略，这个情况可能会涉及到已经设置了过期时间的和没有设置过期时间的，总之就是在这些key都是可用状态下因为内存不足<strong>不得已</strong>释放空间的时候让用户选择的一个策略。</p><p>内存的释放也不是一次性把所有的都释放，而是释放到满足放下新的key的的条件为止</p><p>redis的淘汰策略通过<code>maxmemory-policy</code>在<code>redis.conf</code>配置文件中进行配置</p><h3 id="_2-1、淘汰策略类型" tabindex="-1"><a class="header-anchor" href="#_2-1、淘汰策略类型"><span>2.1、淘汰策略类型</span></a></h3><h4 id="_2-1-1、noeviction-默认" tabindex="-1"><a class="header-anchor" href="#_2-1-1、noeviction-默认"><span>2.1.1、noeviction（默认）</span></a></h4><p>redis默认不会擅自删除有效的key，如果内存空间不足了，再写新的key的化直接oom，新数据不会写入</p><h4 id="_2-1-2、allkeys-lru" tabindex="-1"><a class="header-anchor" href="#_2-1-2、allkeys-lru"><span>2.1.2、allkeys-lru</span></a></h4><p>从所有的key中，删除最久没有被使用的key</p><h4 id="_2-1-3、allkeys-lfu" tabindex="-1"><a class="header-anchor" href="#_2-1-3、allkeys-lfu"><span>2.1.3、allkeys-lfu</span></a></h4><p>从所有的key中，删除使用频率最少的</p><h4 id="_2-1-4、allkeys-random" tabindex="-1"><a class="header-anchor" href="#_2-1-4、allkeys-random"><span>2.1.4、allkeys-random</span></a></h4><p>从所有的key中随机删除一些key</p><h4 id="_2-1-5、volatile-lru" tabindex="-1"><a class="header-anchor" href="#_2-1-5、volatile-lru"><span>2.1.5、volatile-lru</span></a></h4><p>从设置了过期时间的所有key中，删除最久没有被使用的key</p><h4 id="_2-1-6、volatile-lfu" tabindex="-1"><a class="header-anchor" href="#_2-1-6、volatile-lfu"><span>2.1.6、volatile-lfu</span></a></h4><p>从所有设置了过期时间的key中，删除最少使用的key</p><h4 id="_2-1-7、volatile-random" tabindex="-1"><a class="header-anchor" href="#_2-1-7、volatile-random"><span>2.1.7、volatile-random</span></a></h4><p>从所有设置了过期时间的key中，随机删除一些key</p><h4 id="_2-1-8、volatile-ttl" tabindex="-1"><a class="header-anchor" href="#_2-1-8、volatile-ttl"><span>2.1.8、volatile-ttl</span></a></h4><p>从所有设置了过期时间的key中，删除最近要过期的key</p><h3 id="_2-2、淘汰流程" tabindex="-1"><a class="header-anchor" href="#_2-2、淘汰流程"><span>2.2、淘汰流程</span></a></h3><p><img src="`+u+`" alt="image-20260122175954139"></p><p>上图展示了redis在内存不足的时候的淘汰流程，简单概述一下：</p><ul><li><p>1、用户在进行写操作的时候，首先会判断一下redis可用内存是否足够写新的数据，如果充足，直接执行，并返回执行结果</p></li><li><p>2、如果内存不够，则会触发redis的淘汰流程，redis会先判断一下用户有没有配置其它的淘汰策略，如果没有配置而是采用默认的<code>noeviction</code>，则本次写失败，报oom，只能读不能写</p></li><li><p>3、如果用户配置了其它的淘汰策略，则会根据对应的策略找出适合淘汰的key</p><ul><li>① 根据<code>maxmemory-samples</code>采样指定的数据</li><li>② 根据<code>maxmemory-policy</code>配置的策略，按照对应的算法计算采样数据的各个淘汰值</li></ul></li><li><p>4、计算出采样数据的淘汰值之后，会跟淘汰池里边的“待淘汰”的数据进行比较。来判断是否需要也加入到淘汰池里边去</p><blockquote><p>淘汰池是一个容量为16的有序列表，进入淘汰池说明这些key是待淘汰的</p></blockquote><ul><li>① 如果淘汰池没有满，则将采样的数据加入到淘汰池中去</li><li>② 如果淘汰池满了，则用采样的数据的淘汰值跟淘汰池中的数据的淘汰值进行比较，如果发现有比自己的淘汰值小的，则将其从淘汰池移除，将自己放进去，并且按照顺序做好排序，淘汰值越大越往后</li></ul></li><li><p>5、从最末尾开始删除对应的key，然后将其从淘汰池移除</p></li></ul><p>具体的源码在<code>evict.c</code>的<code>freeMemoryIfNeeded</code>方法：</p><div class="language-c line-numbers-mode" data-highlighter="prismjs" data-ext="c" data-title="c"><pre><code><span class="line"><span class="token keyword">int</span> <span class="token function">freeMemoryIfNeeded</span><span class="token punctuation">(</span><span class="token keyword">void</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">int</span> keys_freed <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">/* By default replicas should ignore maxmemory</span>
<span class="line">     * and just be masters exact copies. */</span></span>
<span class="line">    <span class="token comment">//从库是否忽略内存淘汰限制</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>server<span class="token punctuation">.</span>masterhost <span class="token operator">&amp;&amp;</span> server<span class="token punctuation">.</span>repl_slave_ignore_maxmemory<span class="token punctuation">)</span> <span class="token keyword">return</span> C_OK<span class="token punctuation">;</span></span>
<span class="line">    <span class="token class-name">size_t</span> mem_reported<span class="token punctuation">,</span> mem_tofree<span class="token punctuation">,</span> mem_freed<span class="token punctuation">;</span></span>
<span class="line">    <span class="token class-name">mstime_t</span> latency<span class="token punctuation">,</span> eviction_latency<span class="token punctuation">,</span> lazyfree_latency<span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">long</span> <span class="token keyword">long</span> delta<span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">int</span> slaves <span class="token operator">=</span> <span class="token function">listLength</span><span class="token punctuation">(</span>server<span class="token punctuation">.</span>slaves<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">int</span> result <span class="token operator">=</span> C_ERR<span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">/* When clients are paused the dataset should be static not just from the </span>
<span class="line">     * POV of clients not being able to write, but also from the POV of </span>
<span class="line">     * expires and evictions of keys not being performed. </span>
<span class="line">     */</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">clientsArePaused</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span> C_OK<span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">//判断内存是否满，如果没有超过内存，直接返回</span></span>
<span class="line">    <span class="token keyword">if</span><span class="token punctuation">(</span><span class="token function">getMaxmemoryState</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>mem_reported<span class="token punctuation">,</span><span class="token constant">NULL</span><span class="token punctuation">,</span><span class="token operator">&amp;</span>mem_tofree<span class="token punctuation">,</span><span class="token constant">NULL</span><span class="token punctuation">)</span> <span class="token operator">==</span> C_OK<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">return</span> C_OK<span class="token punctuation">;</span></span>
<span class="line">    mem_freed <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">latencyStartMonitor</span><span class="token punctuation">(</span>latency<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>server<span class="token punctuation">.</span>maxmemory_policy <span class="token operator">==</span> MAXMEMORY_NO_EVICTION<span class="token punctuation">)</span></span>
<span class="line">        <span class="token comment">//如果策略为不淘汰数据，直接报错OOM</span></span>
<span class="line">        <span class="token keyword">goto</span> cant_free<span class="token punctuation">;</span> <span class="token comment">/* We need to free memory, but policy forbids. */</span></span>
<span class="line">    <span class="token comment">//到这一步肯定是内存不够 如果释放的内存不够 一直自旋释放内存</span></span>
<span class="line">    <span class="token keyword">while</span> <span class="token punctuation">(</span>mem_freed <span class="token operator">&lt;</span> mem_tofree<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">int</span> j<span class="token punctuation">,</span> k<span class="token punctuation">,</span> i<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">static</span> <span class="token keyword">unsigned</span> <span class="token keyword">int</span> next_db <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">        sds bestkey <span class="token operator">=</span> <span class="token constant">NULL</span><span class="token punctuation">;</span> <span class="token comment">//定义最好的删除的key</span></span>
<span class="line">        <span class="token keyword">int</span> bestdbid<span class="token punctuation">;</span></span>
<span class="line">        redisDb <span class="token operator">*</span>db<span class="token punctuation">;</span></span>
<span class="line">        dict <span class="token operator">*</span>dict<span class="token punctuation">;</span></span>
<span class="line">        dictEntry <span class="token operator">*</span>de<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>server<span class="token punctuation">.</span>maxmemory_policy <span class="token operator">&amp;</span> <span class="token punctuation">(</span>MAXMEMORY_FLAG_LRU<span class="token operator">|</span>MAXMEMORY_FLAG_LFU<span class="token punctuation">)</span> <span class="token operator">||</span> server<span class="token punctuation">.</span>maxmemory_policy <span class="token operator">==</span> MAXMEMORY_VOLATILE_TTL<span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">//如果淘汰算法是LRU | LFU | TTL</span></span>
<span class="line">            <span class="token keyword">struct</span> <span class="token class-name">evictionPoolEntry</span> <span class="token operator">*</span>pool <span class="token operator">=</span> EvictionPoolLRU<span class="token punctuation">;</span> <span class="token comment">//淘汰池 默认大小16</span></span>
<span class="line">            <span class="token comment">//自旋找到合适的要淘汰的key为止</span></span>
<span class="line">            <span class="token keyword">while</span><span class="token punctuation">(</span>bestkey <span class="token operator">==</span> <span class="token constant">NULL</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token keyword">unsigned</span> <span class="token keyword">long</span> total_keys <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span> keys<span class="token punctuation">;</span></span>
<span class="line">                <span class="token comment">/* We don&#39;t want to make local-db choices when expiring keys, </span>
<span class="line">                 * so to start populate the eviction pool sampling keys from </span>
<span class="line">                 * every DB. */</span></span>
<span class="line">                <span class="token keyword">for</span> <span class="token punctuation">(</span>i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> server<span class="token punctuation">.</span>dbnum<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token comment">//去不同的DB查找</span></span>
<span class="line">                    db <span class="token operator">=</span> server<span class="token punctuation">.</span>db<span class="token operator">+</span>i<span class="token punctuation">;</span></span>
<span class="line">                    <span class="token comment">//判断需要淘汰的范围 是所有数据还是过期的数据</span></span>
<span class="line">                    dict <span class="token operator">=</span> <span class="token punctuation">(</span>server<span class="token punctuation">.</span>maxmemory_policy <span class="token operator">&amp;</span> MAXMEMORY_FLAG_ALLKEYS<span class="token punctuation">)</span> <span class="token operator">?</span> db<span class="token operator">-&gt;</span>dict <span class="token operator">:</span> db<span class="token operator">-&gt;</span>expires<span class="token punctuation">;</span></span>
<span class="line">                    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token punctuation">(</span>keys <span class="token operator">=</span> <span class="token function">dictSize</span><span class="token punctuation">(</span>dict<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">!=</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                        <span class="token function">evictionPoolPopulate</span><span class="token punctuation">(</span>i<span class="token punctuation">,</span> dict<span class="token punctuation">,</span> db<span class="token operator">-&gt;</span>dict<span class="token punctuation">,</span> pool<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">//关键方法：去从范围中取样拿到最适合淘汰的数据</span></span>
<span class="line">                        <span class="token punctuation">(</span>i<span class="token punctuation">,</span> dict<span class="token punctuation">,</span> db<span class="token operator">-&gt;</span>dict<span class="token punctuation">,</span> pool<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                        total_keys <span class="token operator">+=</span> keys<span class="token punctuation">;</span></span>
<span class="line">                    <span class="token punctuation">}</span></span>
<span class="line">                <span class="token punctuation">}</span></span>
<span class="line">                <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>total_keys<span class="token punctuation">)</span> <span class="token keyword">break</span><span class="token punctuation">;</span> <span class="token comment">/* No keys to evict. */</span> <span class="token comment">//没有key过期</span></span>
<span class="line">                <span class="token comment">/* Go backward from best to worst element to evict. */</span></span>
<span class="line">                <span class="token keyword">for</span> <span class="token punctuation">(</span>k <span class="token operator">=</span> EVPOOL_SIZE<span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">;</span> k <span class="token operator">&gt;=</span> <span class="token number">0</span><span class="token punctuation">;</span> k<span class="token operator">--</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                    <span class="token keyword">if</span> <span class="token punctuation">(</span>pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>key <span class="token operator">==</span> <span class="token constant">NULL</span><span class="token punctuation">)</span> <span class="token keyword">continue</span><span class="token punctuation">;</span></span>
<span class="line">                    bestdbid <span class="token operator">=</span> pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>dbid<span class="token punctuation">;</span></span>
<span class="line">                    <span class="token keyword">if</span> <span class="token punctuation">(</span>server<span class="token punctuation">.</span>maxmemory_policy <span class="token operator">&amp;</span> MAXMEMORY_FLAG_ALLKEYS<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                        de <span class="token operator">=</span> <span class="token function">dictFind</span><span class="token punctuation">(</span>server<span class="token punctuation">.</span>db<span class="token punctuation">[</span>pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>dbid<span class="token punctuation">]</span><span class="token punctuation">.</span>dict<span class="token punctuation">,</span> pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>key<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">                        de <span class="token operator">=</span> <span class="token function">dictFind</span><span class="token punctuation">(</span>server<span class="token punctuation">.</span>db<span class="token punctuation">[</span>pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>dbid<span class="token punctuation">]</span><span class="token punctuation">.</span>expires<span class="token punctuation">,</span> pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>key<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                    <span class="token punctuation">}</span></span>
<span class="line">                    <span class="token comment">/* Remove the entry from the pool. */</span></span>
<span class="line">                    <span class="token keyword">if</span> <span class="token punctuation">(</span>pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>key <span class="token operator">!=</span> pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>cached<span class="token punctuation">)</span></span>
<span class="line">                        <span class="token function">sdsfree</span><span class="token punctuation">(</span>pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>key<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                    pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>key <span class="token operator">=</span> <span class="token constant">NULL</span><span class="token punctuation">;</span></span>
<span class="line">                    pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>idle <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">                    <span class="token comment">/* If the key exists, is our pick. Otherwise it is </span>
<span class="line">                     * a ghost and we need to try the next element. */</span></span>
<span class="line">                    <span class="token keyword">if</span> <span class="token punctuation">(</span>de<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                        bestkey <span class="token operator">=</span> <span class="token function">dictGetKey</span><span class="token punctuation">(</span>de<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                        <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line">                    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">                        <span class="token comment">/* Ghost... Iterate again. */</span></span>
<span class="line">                    <span class="token punctuation">}</span></span>
<span class="line">                <span class="token punctuation">}</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token comment">/* volatile-random and allkeys-random policy */</span></span>
<span class="line">        <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>server<span class="token punctuation">.</span>maxmemory_policy <span class="token operator">==</span> MAXMEMORY_ALLKEYS_RANDOM <span class="token operator">||</span> server<span class="token punctuation">.</span>maxmemory_policy <span class="token operator">==</span> MAXMEMORY_VOLATILE_RANDOM<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">/* When evicting a random key, we try to evict a key for </span>
<span class="line">             * each DB, so we use the static &#39;next_db&#39; variable to </span>
<span class="line">             * incrementally visit all DBs. */</span></span>
<span class="line">             <span class="token keyword">for</span> <span class="token punctuation">(</span>i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> server<span class="token punctuation">.</span>dbnum<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                 j <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token operator">++</span>next_db<span class="token punctuation">)</span> <span class="token operator">%</span> server<span class="token punctuation">.</span>dbnum<span class="token punctuation">;</span></span>
<span class="line">                 db <span class="token operator">=</span> server<span class="token punctuation">.</span>db<span class="token operator">+</span>j<span class="token punctuation">;</span></span>
<span class="line">                 dict <span class="token operator">=</span> <span class="token punctuation">(</span>server<span class="token punctuation">.</span>maxmemory_policy <span class="token operator">==</span> MAXMEMORY_ALLKEYS_RANDOM<span class="token punctuation">)</span> <span class="token operator">?</span> db<span class="token operator">-&gt;</span>dict <span class="token operator">:</span> db<span class="token operator">-&gt;</span>expires<span class="token punctuation">;</span></span>
<span class="line">                 <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">dictSize</span><span class="token punctuation">(</span>dict<span class="token punctuation">)</span> <span class="token operator">!=</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                     de <span class="token operator">=</span> <span class="token function">dictGetRandomKey</span><span class="token punctuation">(</span>dict<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                     bestkey <span class="token operator">=</span> <span class="token function">dictGetKey</span><span class="token punctuation">(</span>de<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                     bestdbid <span class="token operator">=</span> j<span class="token punctuation">;</span></span>
<span class="line">                     <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line">                 <span class="token punctuation">}</span></span>
<span class="line">             <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token comment">/* Finally remove the selected key. */</span> <span class="token comment">// 移除这个key</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>bestkey<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            db <span class="token operator">=</span> server<span class="token punctuation">.</span>db<span class="token operator">+</span>bestdbid<span class="token punctuation">;</span></span>
<span class="line">            robj <span class="token operator">*</span>keyobj <span class="token operator">=</span> <span class="token function">createStringObject</span><span class="token punctuation">(</span>bestkey<span class="token punctuation">,</span><span class="token function">sdslen</span><span class="token punctuation">(</span>bestkey<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token function">propagateExpire</span><span class="token punctuation">(</span>db<span class="token punctuation">,</span>keyobj<span class="token punctuation">,</span>server<span class="token punctuation">.</span>lazyfree_lazy_eviction<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token comment">/* We compute the amount of memory freed by db*Delete() alone. </span>
<span class="line">             * It is possible that actually the memory needed to propagate </span>
<span class="line">             * the DEL in AOF and replication link is greater than the one </span>
<span class="line">             * we are freeing removing the key, but we can&#39;t account for </span>
<span class="line">             * that otherwise we would never exit the loop. </span>
<span class="line">             *</span>
<span class="line">             * AOF and Output buffer memory will be freed eventually so </span>
<span class="line">             * we only care about memory used by the key space. */</span></span>
<span class="line">            delta <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">long</span> <span class="token keyword">long</span><span class="token punctuation">)</span> <span class="token function">zmalloc_used_memory</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token function">latencyStartMonitor</span><span class="token punctuation">(</span>eviction_latency<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token comment">//如果是异步淘汰 会进行异步淘汰</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>server<span class="token punctuation">.</span>lazyfree_lazy_eviction<span class="token punctuation">)</span></span>
<span class="line">                <span class="token function">dbAsyncDelete</span><span class="token punctuation">(</span>db<span class="token punctuation">,</span>keyobj<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">else</span></span>
<span class="line">                <span class="token comment">//同步淘汰</span></span>
<span class="line">                <span class="token function">dbSyncDelete</span><span class="token punctuation">(</span>db<span class="token punctuation">,</span>keyobj<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token function">signalModifiedKey</span><span class="token punctuation">(</span><span class="token constant">NULL</span><span class="token punctuation">,</span>db<span class="token punctuation">,</span>keyobj<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token function">latencyEndMonitor</span><span class="token punctuation">(</span>eviction_latency<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token function">latencyAddSampleIfNeeded</span><span class="token punctuation">(</span><span class="token string">&quot;evictiondel&quot;</span><span class="token punctuation">,</span>eviction_latency<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            delta <span class="token operator">-=</span> <span class="token punctuation">(</span><span class="token keyword">long</span> <span class="token keyword">long</span><span class="token punctuation">)</span> <span class="token function">zmalloc_used_memory</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            mem_freed <span class="token operator">+=</span> delta<span class="token punctuation">;</span></span>
<span class="line">            server<span class="token punctuation">.</span>stat_evictedkeys<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token function">notifyKeyspaceEvent</span><span class="token punctuation">(</span>NOTIFY_EVICTED<span class="token punctuation">,</span> <span class="token string">&quot;evicted&quot;</span><span class="token punctuation">,</span> keyobj<span class="token punctuation">,</span> db<span class="token operator">-&gt;</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token function">decrRefCount</span><span class="token punctuation">(</span>keyobj<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            keys_freed<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token comment">/* When the memory to free starts to be big enough, we may </span>
<span class="line">             * start spending so much time here that is impossible to </span>
<span class="line">             * deliver data to the slaves fast enough, so we force the </span>
<span class="line">             * transmission here inside the loop. */</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>slaves<span class="token punctuation">)</span> <span class="token function">flushSlavesOutputBuffers</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token comment">/* Normally our stop condition is the ability to release </span>
<span class="line">             * a fixed, pre-computed amount of memory. However when we </span>
<span class="line">             * are deleting objects in another thread, it&#39;s better to </span>
<span class="line">             * check, from time to time, if we already reached our target </span>
<span class="line">             * memory, since the &quot;mem_freed&quot; amount is computed only </span>
<span class="line">             * across the dbAsyncDelete() call, while the thread can </span>
<span class="line">             * release the memory all the time. */</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>server<span class="token punctuation">.</span>lazyfree_lazy_eviction <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span><span class="token punctuation">(</span>keys_freed <span class="token operator">%</span> <span class="token number">16</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">getMaxmemoryState</span><span class="token punctuation">(</span><span class="token constant">NULL</span><span class="token punctuation">,</span><span class="token constant">NULL</span><span class="token punctuation">,</span><span class="token constant">NULL</span><span class="token punctuation">,</span><span class="token constant">NULL</span><span class="token punctuation">)</span> <span class="token operator">==</span> C_OK<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                    <span class="token comment">/* Let&#39;s satisfy our stop condition.*/</span></span>
<span class="line">                    mem_freed <span class="token operator">=</span> mem_tofree<span class="token punctuation">;</span></span>
<span class="line">                <span class="token punctuation">}</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">goto</span> cant_free<span class="token punctuation">;</span> <span class="token comment">/* nothing to free... */</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    result <span class="token operator">=</span> C_OK<span class="token punctuation">;</span></span>
<span class="line">    cant_free<span class="token operator">:</span></span>
<span class="line">    <span class="token comment">/* We are here if we are not able to reclaim memory. There is only one </span>
<span class="line">     * last thing we can try: check if the lazyfree thread has jobs in queue </span>
<span class="line">     * and wait... */</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>result <span class="token operator">!=</span> C_OK<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token function">latencyStartMonitor</span><span class="token punctuation">(</span>lazyfree_latency<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">while</span><span class="token punctuation">(</span><span class="token function">bioPendingJobsOfType</span><span class="token punctuation">(</span>BIO_LAZY_FREE<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">getMaxmemoryState</span><span class="token punctuation">(</span><span class="token constant">NULL</span><span class="token punctuation">,</span><span class="token constant">NULL</span><span class="token punctuation">,</span><span class="token constant">NULL</span><span class="token punctuation">,</span><span class="token constant">NULL</span><span class="token punctuation">)</span> <span class="token operator">==</span> C_OK<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                result <span class="token operator">=</span> C_OK<span class="token punctuation">;</span></span>
<span class="line">                <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">            <span class="token function">usleep</span><span class="token punctuation">(</span><span class="token number">1000</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">            <span class="token function">latencyEndMonitor</span><span class="token punctuation">(</span>lazyfree_latency<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token function">latencyAddSampleIfNeeded</span><span class="token punctuation">(</span><span class="token string">&quot;evictionlazyfree&quot;</span><span class="token punctuation">,</span>lazyfree_latency<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token function">latencyEndMonitor</span><span class="token punctuation">(</span>latency<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token function">latencyAddSampleIfNeeded</span><span class="token punctuation">(</span><span class="token string">&quot;eviction-cycle&quot;</span><span class="token punctuation">,</span>latency<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">return</span> result<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>其中<code>evictionPoolPopulate</code>方法如下：</p><div class="language-c line-numbers-mode" data-highlighter="prismjs" data-ext="c" data-title="c"><pre><code><span class="line"><span class="token keyword">void</span> <span class="token function">evictionPoolPopulate</span><span class="token punctuation">(</span><span class="token keyword">int</span> dbid<span class="token punctuation">,</span> dict <span class="token operator">*</span>sampledict<span class="token punctuation">,</span> dict <span class="token operator">*</span>keydict<span class="token punctuation">,</span> <span class="token keyword">struct</span> <span class="token class-name">evictionPoolEntry</span> <span class="token operator">*</span>pool<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">int</span> j<span class="token punctuation">,</span> k<span class="token punctuation">,</span> count<span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">//需要取样的数据</span></span>
<span class="line">    dictEntry <span class="token operator">*</span>samples<span class="token punctuation">[</span>server<span class="token punctuation">.</span>maxmemory_samples<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">//随机从需要取样的范围中得到取样的数据</span></span>
<span class="line">    count <span class="token operator">=</span> <span class="token function">dictGetSomeKeys</span><span class="token punctuation">(</span>sampledict<span class="token punctuation">,</span>samples<span class="token punctuation">,</span>server<span class="token punctuation">.</span>maxmemory_samples<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">//循环取样数据</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span>j <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> j <span class="token operator">&lt;</span> count<span class="token punctuation">;</span> j<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">unsigned</span> <span class="token keyword">long</span> <span class="token keyword">long</span> idle<span class="token punctuation">;</span></span>
<span class="line">        sds key<span class="token punctuation">;</span></span>
<span class="line">        robj <span class="token operator">*</span>o<span class="token punctuation">;</span></span>
<span class="line">        dictEntry <span class="token operator">*</span>de<span class="token punctuation">;</span></span>
<span class="line">        de <span class="token operator">=</span> samples<span class="token punctuation">[</span>j<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">        key <span class="token operator">=</span> <span class="token function">dictGetKey</span><span class="token punctuation">(</span>de<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token comment">/* If the dictionary we are sampling from is not the main</span>
<span class="line">         * dictionary (but the expires one) we need to lookup the key </span>
<span class="line">         * again in the key dictionary to obtain the value object. */</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>server<span class="token punctuation">.</span>maxmemory_policy <span class="token operator">!=</span> MAXMEMORY_VOLATILE_TTL<span class="token punctuation">)</span> <span class="token punctuation">{</span> </span>
<span class="line">            <span class="token comment">//如果是ttl，只能从带有过期时间的数据中获取,所以不需要获取对象，其他的淘汰策略都需要去我们的键值对中获取值对象</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>sampledict <span class="token operator">!=</span> keydict<span class="token punctuation">)</span> de <span class="token operator">=</span> <span class="token function">dictFind</span><span class="token punctuation">(</span>keydict<span class="token punctuation">,</span> key<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            o <span class="token operator">=</span> <span class="token function">dictGetVal</span><span class="token punctuation">(</span>de<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token comment">/* Calculate the idle time according to the policy. This is called</span>
<span class="line">         * idle just because the code initially handled LRU, but is in fact </span>
<span class="line">         * just a score where an higher score means better candidate. */</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>server<span class="token punctuation">.</span>maxmemory_policy <span class="token operator">&amp;</span> MAXMEMORY_FLAG_LRU<span class="token punctuation">)</span><span class="token punctuation">{</span> </span>
<span class="line">            <span class="token comment">//如果是LRU算法，采用LRU算法得到最长时间没访问的</span></span>
<span class="line">            idle <span class="token operator">=</span> <span class="token function">estimateObjectIdleTime</span><span class="token punctuation">(</span>o<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>server<span class="token punctuation">.</span>maxmemory_policy <span class="token operator">&amp;</span> MAXMEMORY_FLAG_LFU<span class="token punctuation">)</span> <span class="token punctuation">{</span> </span>
<span class="line">            <span class="token comment">//如果是LFU算法，根据LRU算法得到最少访问的，但是用255-值 所以idle越大，越容易淘汰</span></span>
<span class="line">            <span class="token comment">/* When we use an LRU policy, we sort the keys by idle time </span>
<span class="line">             * so that we expire keys starting from greater idle time. </span>
<span class="line">             * However when the policy is an LFU one, we have a frequency </span>
<span class="line">             * estimation, and we want to evict keys with lower frequency </span>
<span class="line">             * first. So inside the pool we put objects using the inverted </span>
<span class="line">             * frequency subtracting the actual frequency to the maximum </span>
<span class="line">             * frequency of 255. */</span></span>
<span class="line">            idle <span class="token operator">=</span> <span class="token number">255</span><span class="token operator">-</span><span class="token function">LFUDecrAndReturn</span><span class="token punctuation">(</span>o<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>server<span class="token punctuation">.</span>maxmemory_policy <span class="token operator">==</span> MAXMEMORY_VOLATILE_TTL<span class="token punctuation">)</span> <span class="token punctuation">{</span> </span>
<span class="line">            <span class="token comment">//ttl 直接根据时间来</span></span>
<span class="line">            <span class="token comment">/* In this case the sooner the expire the better. */</span></span>
<span class="line">            idle <span class="token operator">=</span> ULLONG_MAX <span class="token operator">-</span> <span class="token punctuation">(</span><span class="token keyword">long</span><span class="token punctuation">)</span><span class="token function">dictGetVal</span><span class="token punctuation">(</span>de<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token function">serverPanic</span><span class="token punctuation">(</span><span class="token string">&quot;Unknown eviction policy in evictionPoolPopulate()&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token comment">/* Insert the element inside the pool. </span>
<span class="line">         * First, find the first empty bucket or the first populated</span>
<span class="line">         * bucket that has an idle time smaller than our idle time. */</span></span>
<span class="line">        <span class="token comment">//讲取样的数据，计算好淘汰的idle后，放入淘汰池中</span></span>
<span class="line">        k <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> </span>
<span class="line">        <span class="token keyword">while</span> <span class="token punctuation">(</span>k <span class="token operator">&lt;</span> EVPOOL_SIZE <span class="token operator">&amp;&amp;</span> pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>key <span class="token operator">&amp;&amp;</span> pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>idle <span class="token operator">&lt;</span> idle<span class="token punctuation">)</span> k<span class="token operator">++</span><span class="token punctuation">;</span> </span>
<span class="line">        <span class="token comment">//自旋，找到淘汰池中比当前key的idle小的最后一个下标</span></span>
<span class="line">        <span class="token comment">//k=0说明上面循环没进，也就是淘汰池中的所有数据都比当前数据的idle大，并且淘汰池的最后一个不为空，说明淘汰池也是满的。优先淘汰淘汰池的</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>k <span class="token operator">==</span> <span class="token number">0</span> <span class="token operator">&amp;&amp;</span> pool<span class="token punctuation">[</span>EVPOOL_SIZE<span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">.</span>key <span class="token operator">!=</span> <span class="token constant">NULL</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">/* Can&#39;t insert if the element is &lt; the worst element we have </span>
<span class="line">             * and there are no empty buckets. */</span></span>
<span class="line">            <span class="token keyword">continue</span><span class="token punctuation">;</span> </span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>k <span class="token operator">&lt;</span> EVPOOL_SIZE <span class="token operator">&amp;&amp;</span> pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>key <span class="token operator">==</span> <span class="token constant">NULL</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token comment">//插入到桶后面 不管</span></span>
<span class="line">            <span class="token comment">/* Inserting into empty position. No setup needed before insert. */</span></span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span> <span class="token comment">//插入到中间 会进行淘汰池的数据移动</span></span>
<span class="line">            <span class="token comment">/* Inserting in the middle. Now k points to the first element </span>
<span class="line">             * greater than the element to insert. */</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>pool<span class="token punctuation">[</span>EVPOOL_SIZE<span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">.</span>key <span class="token operator">==</span> <span class="token constant">NULL</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token comment">/* Free space on the right? Insert at k shifting </span>
<span class="line">                 * all the elements from k to end to the right. */</span></span>
<span class="line">                <span class="token comment">/* Save SDS before overwriting. */</span></span>
<span class="line">                sds cached <span class="token operator">=</span> pool<span class="token punctuation">[</span>EVPOOL_SIZE<span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">.</span>cached<span class="token punctuation">;</span></span>
<span class="line">                <span class="token function">memmove</span><span class="token punctuation">(</span>pool<span class="token operator">+</span>k<span class="token operator">+</span><span class="token number">1</span><span class="token punctuation">,</span>pool<span class="token operator">+</span>k<span class="token punctuation">,</span> <span class="token keyword">sizeof</span><span class="token punctuation">(</span>pool<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">*</span><span class="token punctuation">(</span>EVPOOL_SIZE<span class="token operator">-</span>k<span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>cached <span class="token operator">=</span> cached<span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token comment">/* No free space on right? Insert at k-1 */</span></span>
<span class="line">                k<span class="token operator">--</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token comment">/* Shift all elements on the left of k (included) to the </span>
<span class="line">                 * left, so we discard the element with smaller idle time. */</span></span>
<span class="line">                sds cached <span class="token operator">=</span> pool<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">.</span>cached<span class="token punctuation">;</span> <span class="token comment">/* Save SDS before overwriting. */</span></span>
<span class="line">                <span class="token keyword">if</span> <span class="token punctuation">(</span>pool<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">.</span>key <span class="token operator">!=</span> pool<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">.</span>cached<span class="token punctuation">)</span></span>
<span class="line">                    <span class="token function">sdsfree</span><span class="token punctuation">(</span>pool<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">.</span>key<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token function">memmove</span><span class="token punctuation">(</span>pool<span class="token punctuation">,</span>pool<span class="token operator">+</span><span class="token number">1</span><span class="token punctuation">,</span><span class="token keyword">sizeof</span><span class="token punctuation">(</span>pool<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">*</span>k<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token comment">//假如当前数据比淘汰池的有些数据大，那么淘汰最小的</span></span>
<span class="line">                pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>cached <span class="token operator">=</span> cached<span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token comment">/* Try to reuse the cached SDS string allocated in the pool entry, </span>
<span class="line">         * because allocating and deallocating this object is costly </span>
<span class="line">         * (according to the profiler, not my fantasy. Remember: </span>
<span class="line">         * premature optimizbla bla bla bla. */</span></span>
<span class="line">        <span class="token comment">//以下所及，将当前的放入淘汰池 </span></span>
<span class="line">        <span class="token keyword">int</span> klen <span class="token operator">=</span> <span class="token function">sdslen</span><span class="token punctuation">(</span>key<span class="token punctuation">)</span><span class="token punctuation">;</span> </span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>klen <span class="token operator">&gt;</span> EVPOOL_CACHED_SDS_SIZE<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>key <span class="token operator">=</span> <span class="token function">sdsdup</span><span class="token punctuation">(</span>key<span class="token punctuation">)</span><span class="token punctuation">;</span> </span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span> </span>
<span class="line">            <span class="token function">memcpy</span><span class="token punctuation">(</span>pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>cached<span class="token punctuation">,</span>key<span class="token punctuation">,</span>klen<span class="token operator">+</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span> </span>
<span class="line">            <span class="token function">sdssetlen</span><span class="token punctuation">(</span>pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>cached<span class="token punctuation">,</span>klen<span class="token punctuation">)</span><span class="token punctuation">;</span> </span>
<span class="line">            pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>key <span class="token operator">=</span> pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>cached<span class="token punctuation">;</span> </span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>idle <span class="token operator">=</span> idle<span class="token punctuation">;</span> </span>
<span class="line">        pool<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>dbid <span class="token operator">=</span> dbid<span class="token punctuation">;</span> </span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-3、lru算法" tabindex="-1"><a class="header-anchor" href="#_2-3、lru算法"><span>2.3、LRU算法</span></a></h3><p>LRU（Least Recently Used），顾名思义，就是找久未被使用的数据，越最近使用越靠前，是一个时间维度的度量衡。在redis的淘汰策略中，LRU算法会先计算key多久未被使用了，越久未被使用，淘汰值就会越大，也就越优先被淘汰</p><p><strong>原理：</strong></p><ul><li>① 所有的value在redis中都会被封装成一个RedisObject对象，在这个对象中，有一个属性lru</li></ul><div class="language-c line-numbers-mode" data-highlighter="prismjs" data-ext="c" data-title="c"><pre><code><span class="line"><span class="token keyword">typedef</span> <span class="token keyword">struct</span> <span class="token class-name">redisObject</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">unsigned</span> type<span class="token operator">:</span><span class="token number">4</span><span class="token punctuation">;</span>  <span class="token comment">//数据类型，string、hash、list、set...</span></span>
<span class="line">	<span class="token keyword">unsigned</span> encoding<span class="token operator">:</span><span class="token number">4</span><span class="token punctuation">;</span> <span class="token comment">//底层的数据结构，比如skiplist</span></span>
<span class="line">	<span class="token keyword">unsigned</span> lru<span class="token operator">:</span>LRU_BITS<span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">/* LRU time (relative to global lru_clock) or </span>
<span class="line">     * LFU data (least significant 8 bits frequency</span>
<span class="line">     * and most significant 16 bits access time). */</span></span>
<span class="line">	<span class="token keyword">int</span> refcount<span class="token punctuation">;</span></span>
<span class="line">	<span class="token keyword">void</span> <span class="token operator">*</span>ptr<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span> robj<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>lru是24位：代表对象最后被访问的秒单位的最后24位：<code>秒单位 &amp; ((1&lt;&lt;24)-1)</code></p><p>如果是lru的时候，这个属性记录的就是lru时钟</p><p>如果是lru的时候，低8位记录的就是使用的次数，高16位代表的是时间</p><ul><li><p>② 计算当前key多久未被使用</p><ul><li>假如我们lruclock=当前时间的秒单位的最后24bit</li><li>如果当前时间的低24位比这个redis对象的lru大：lru_clock-redisObject.lru</li><li>如果当前时间的低24位比这个redis对象的lru小：lru_clock+（24位最大值-redisObject.lru）</li></ul><p>参考<code>evict.c</code>的<code>estimateObjectIdleTime</code>方法</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java" data-title="java"><pre><code><span class="line">unsigned <span class="token keyword">long</span> <span class="token keyword">long</span> <span class="token function">estimateObjectIdleTime</span><span class="token punctuation">(</span>robj <span class="token operator">*</span>o<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token comment">//获取秒单位时间的最后24位</span></span>
<span class="line">	unsigned <span class="token keyword">long</span> <span class="token keyword">long</span> lruclock <span class="token operator">=</span> <span class="token function">LRU_CLOCK</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">	<span class="token comment">//因为只有24位，所有最大的值为2的24次方-1</span></span>
<span class="line">	<span class="token comment">//超过最大值从0开始，所以需要判断lruclock（当前系统时间）跟缓存对象的lru字段的大小</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>lruclock <span class="token operator">&gt;=</span> o<span class="token operator">-&gt;</span>lru<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">//如果lruclock&gt;=robj.lru，返回lruclock-o-&gt;lru，再转换单位</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token punctuation">(</span>lruclock <span class="token operator">-</span> o<span class="token operator">-&gt;</span>lru<span class="token punctuation">)</span> <span class="token operator">*</span> <span class="token constant">LRU_CLOCK_RESOLUTION</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">//否则采用lruclock + (LRU_CLOCK_MAX - o-&gt;lru)，得到对象的值越小，返回的值越大，越大越容易被淘汰</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token punctuation">(</span>lruclock <span class="token operator">+</span> <span class="token punctuation">(</span><span class="token constant">LRU_CLOCK_MAX</span> <span class="token operator">-</span> o<span class="token operator">-&gt;</span>lru<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">*</span> <span class="token constant">LRU_CLOCK_RESOLUTION</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ul><h3 id="_2-4、lfu算法" tabindex="-1"><a class="header-anchor" href="#_2-4、lfu算法"><span>2.4、LFU算法</span></a></h3><p>LFU（文 Least Frequently Used），故名思意，就是最不经常使用的，是一个频率或次数维度的度量衡。换句话说就是使用的次数越多，就越靠前，即使很久很久没有被使用了。很显然，这在我们的业务场景可能会存在一定的问题，比如之前的热度key，但是现在已经凉凉了，没什么人用了。这就是 **LFU的时效性问题 **</p><p>在redis中，redis既记录了key最后被访问的分钟单位的最后16bit（高16位），也记录了key被使用的次数（低8位）</p><p><strong>原理：</strong></p><ul><li>① 高16位记录的最后被访问的分钟单位的最后16位，然后计算出这个对象多少分钟没有被访问了</li><li>② 然后redis根据配置的<code>lfu-decay-time</code>（多少分钟没有被访问，次数就减1）的值，计算出来一个值</li></ul><p>参考<code>evict.c</code>的<code>LFUDecrAndReturn</code>方法：</p><div class="language-c line-numbers-mode" data-highlighter="prismjs" data-ext="c" data-title="c"><pre><code><span class="line"><span class="token keyword">unsigned</span> <span class="token keyword">long</span> <span class="token function">LFUDecrAndReturn</span><span class="token punctuation">(</span>robj <span class="token operator">*</span>o<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token comment">//lru字段右移8位，得到前面16位的时间</span></span>
<span class="line">	<span class="token keyword">unsigned</span> <span class="token keyword">long</span> ldt <span class="token operator">=</span> o<span class="token operator">-&gt;</span>lru <span class="token operator">&gt;&gt;</span> <span class="token number">8</span><span class="token punctuation">;</span></span>
<span class="line">	<span class="token comment">//lru字段与255进行&amp;运算（255代表8位的最大值），</span></span>
<span class="line">	<span class="token comment">//得到8位counter值</span></span>
<span class="line">	<span class="token keyword">unsigned</span> <span class="token keyword">long</span> counter <span class="token operator">=</span> o<span class="token operator">-&gt;</span>lru <span class="token operator">&amp;</span> <span class="token number">255</span><span class="token punctuation">;</span></span>
<span class="line">	<span class="token comment">//如果配置了lfu_decay_time，用LFUTimeElapsed(ldt) 除以配置的值</span></span>
<span class="line">	<span class="token comment">//LFUTimeElapsed(ldt)源码见下</span></span>
<span class="line">	<span class="token comment">//总的没访问的分钟时间/配置值，得到每分钟没访问衰减多少</span></span>
<span class="line">	<span class="token keyword">unsigned</span> <span class="token keyword">long</span> num_periods <span class="token operator">=</span> server<span class="token punctuation">.</span>lfu_decay_time <span class="token operator">?</span> <span class="token function">LFUTimeElapsed</span><span class="token punctuation">(</span>ldt<span class="token punctuation">)</span> <span class="token operator">/</span> server<span class="token punctuation">.</span>lfu_decay_time <span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">	<span class="token keyword">if</span> <span class="token punctuation">(</span>num_periods<span class="token punctuation">)</span></span>
<span class="line">		<span class="token comment">//不能减少为负数，非负数用couter值减去衰减值</span></span>
<span class="line">		counter <span class="token operator">=</span> <span class="token punctuation">(</span>num_periods <span class="token operator">&gt;</span> counter<span class="token punctuation">)</span> <span class="token operator">?</span> <span class="token number">0</span> <span class="token operator">:</span> counter <span class="token operator">-</span> num_periods<span class="token punctuation">;</span></span>
<span class="line">	<span class="token keyword">return</span> counter<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意：</p><ul><li><p>因为次数是用低8位来记录的，最大值是255</p></li><li><p>如果当前次数小于等于5，每次访问必加1</p></li><li><p>如果当前次数大于5，小于255，则越往上，次数加1的概率越低</p></li></ul><p>参考<code>evict.c</code>的计算次数的方法<code>LFULogIncr</code>：</p><div class="language-c line-numbers-mode" data-highlighter="prismjs" data-ext="c" data-title="c"><pre><code><span class="line"><span class="token class-name">uint8_t</span> <span class="token function">LFULogIncr</span><span class="token punctuation">(</span><span class="token class-name">uint8_t</span> counter<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token comment">//如果已经到最大值255，返回255 ，8位的最大值</span></span>
<span class="line">	<span class="token keyword">if</span> <span class="token punctuation">(</span>counter <span class="token operator">==</span> <span class="token number">255</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token number">255</span><span class="token punctuation">;</span></span>
<span class="line">	<span class="token comment">//得到随机数（0-1）</span></span>
<span class="line">	<span class="token keyword">double</span> r <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">double</span><span class="token punctuation">)</span><span class="token function">rand</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">/</span>RAND_MAX<span class="token punctuation">;</span></span>
<span class="line">	<span class="token comment">//LFU_INIT_VAL表示基数值（在server.h配置）,5</span></span>
<span class="line">	<span class="token keyword">double</span> baseval <span class="token operator">=</span> counter <span class="token operator">-</span> LFU_INIT_VAL<span class="token punctuation">;</span></span>
<span class="line">	<span class="token comment">//如果达不到基数值，表示快不行了，baseval =0</span></span>
<span class="line">	<span class="token keyword">if</span> <span class="token punctuation">(</span>baseval <span class="token operator">&lt;</span> <span class="token number">0</span><span class="token punctuation">)</span> baseval <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">	<span class="token comment">//如果快不行了，肯定给他加counter</span></span>
<span class="line">	<span class="token comment">//不然，按照几率是否加counter，同时跟baseval与</span></span>
<span class="line">	lfu_log_factor相关</span>
<span class="line">	<span class="token comment">//都是在分子，所以2个值越大，加counter几率越小</span></span>
<span class="line">	<span class="token keyword">double</span> p <span class="token operator">=</span> <span class="token number">1.0</span><span class="token operator">/</span><span class="token punctuation">(</span>baseval<span class="token operator">*</span>server<span class="token punctuation">.</span>lfu_log_factor<span class="token operator">+</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">	<span class="token keyword">if</span> <span class="token punctuation">(</span>r <span class="token operator">&lt;</span> p<span class="token punctuation">)</span> counter<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">	<span class="token keyword">return</span> counter<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这就是官网factor配置和使用次数这两个因素对计算出来的结果的影响。简单总结就是factor越大，计算出来的次数结果就增长的越慢，也就是需要key使用更多次才能达到小factor同样的效果</p><p><img src="`+r+'" alt="image-20260122215202066"></p><p>因此，redis通过这个方法，就巧妙地规避了LFU的时效性问题</p><hr><p><img src="https://img.shengxiao.tech/common/huifeidehouer.png" alt="扫码关注"></p>',70))])}const y=e(k,[["render",m]]),h=JSON.parse('{"path":"/series/distribution/Redis/04Redisdeguoqiceluehetaotaicelue.html","title":"4、Redis的过期策略和淘汰策略","lang":"en-US","frontmatter":{"title":"4、Redis的过期策略和淘汰策略","date":"2026-01-22T00:00:00.000Z","categories":["分布式","Redis"],"tags":["分布式","Redis"]},"headers":[{"level":2,"title":"1、过期策略","slug":"_1、过期策略","link":"#_1、过期策略","children":[{"level":3,"title":"1.1、惰性过期","slug":"_1-1、惰性过期","link":"#_1-1、惰性过期","children":[]},{"level":3,"title":"1.2、定期过期","slug":"_1-2、定期过期","link":"#_1-2、定期过期","children":[]}]},{"level":2,"title":"2、淘汰策略","slug":"_2、淘汰策略","link":"#_2、淘汰策略","children":[{"level":3,"title":"2.1、淘汰策略类型","slug":"_2-1、淘汰策略类型","link":"#_2-1、淘汰策略类型","children":[]},{"level":3,"title":"2.2、淘汰流程","slug":"_2-2、淘汰流程","link":"#_2-2、淘汰流程","children":[]},{"level":3,"title":"2.3、LRU算法","slug":"_2-3、lru算法","link":"#_2-3、lru算法","children":[]},{"level":3,"title":"2.4、LFU算法","slug":"_2-4、lfu算法","link":"#_2-4、lfu算法","children":[]}]}],"git":{"createdTime":1789795710000,"updatedTime":1789795710000,"contributors":[{"name":"qknavy","email":"qknavy@aliyun.com","commits":1}]},"filePathRelative":"series/distribution/Redis/04Redis的过期策略和淘汰策略.md"}');export{y as comp,h as data};
